from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parents[1];rows=[]
def add(brand,url,items):
 for title,status,available,missing in items:rows.append(dict(brand=brand,type=title,status=status,available=available,missing=missing,source=url,checked='2026-11-12',brand_artwork_included=False))
add('MIDORI','https://www.midori-store.net/SHOP/183572/list.html',[(t,'部分可做',a,b) for t,a,b in [('回转图案章','选择不同原创图案、换墨色','实体回转机构与原版章面'),('日期章','自填日期与文字章','品牌日期章面与拨轮'),('连续滚轮章','图案重复花边','连续滚动盖章与原版画面'),('浸透线稿章','原创线稿、墨色与缺墨','实体补墨、原版图案'),('习惯／月历功能章','习惯矩阵与内页结构','品牌原版印面'),('多色印泥与补充墨','数字颜色选择','实体油墨与纸张渗透')]])
add('BGM','https://www.bgmlife.jp/products/',[(t,'部分可做' if available else '尚未支持',available or '仅整理官方分类',missing) for t,available,missing in [
('碎片贴','独立彩色贴纸与裁切','品牌原图'),('透明贴','半透明叠贴','真实薄膜触感'),('装饰贴','六套新主题图案','品牌原图'),('便签贴','已有便签、表格素材','品牌原图'),('透明印章','原创线稿章与叠印','实体透明章、品牌原图'),('卷装贴','图案重复花边','实体卷装与剥取'),('和纸胶带','柔和透底与花边','真实纸纤维'),('透明胶带','透明叠贴与图案条','真实薄膜'),('2.5D贴',None,'立体层次'),('绒面贴',None,'绒毛触感'),('立体透明贴',None,'凸起与折射'),('水贴',None,'液体流动'),('糖果贴',None,'透明凸面'),('水晶贴',None,'棱面折射'),('糖霜贴',None,'凸起糖霜质感'),('柔软贴',None,'按压形变'),('刺绣贴',None,'真实线迹触感'),('贴纸工具',None,'实体工具')]])
add('KING JIM / KITTA','https://www.kingjim.co.jp/hitotoki/sp/kitta/lineup.html',[(t,'部分可做',a,b) for t,a,b in [('BASIC','胶带图案与局部裁切','实体预切背纸'),('CLEAR','半透明叠贴','原版图案、薄膜'),('WIDE','自调图案宽度','实体宽幅纸带'),('FLAKE','独立碎片贴','原版图案'),('COLLAGE','透明素材叠贴','真实烫金反光'),('JABARA','连续花边与排列','实体折叠与撕线'),('SPECIAL','可自由组合的数字素材','特殊材质与原版设计')]])
add('古川纸工','https://www.furukawashiko-online.shop/c/furukawa-product/item-fp/flakesticker-fp',[('和纸碎片贴','部分可做','原创图案与和纸感透底','真实和纸、品牌角色与联名图案')])
data=dict(checked='2026-11-12',scope='已核对的4个品牌的部分产品分类，不是商品或SKU全集；其余品牌仍见参考概览',rows=rows)
(root/'docs/craft-coverage.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
body=''.join('<tr>'+''.join('<td>'+escape(str(r[k]))+'</td>' for k in ['brand','type','status','available','missing'])+f'<td><a href="{escape(r["source"])}">官方来源</a></td></tr>' for r in rows)
html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>印章贴纸分类覆盖清单</title><style>body{{background:#f6f2eb;color:#4b5048;font:15px/1.8 system-ui;margin:20px}}main{{max-width:1300px;margin:auto}}.scroll{{overflow:auto}}table{{border-collapse:collapse;min-width:900px;width:100%;background:white}}td,th{{border:1px solid #ddd5c8;padding:10px;text-align:left}}a{{color:#55785e}}select,input{{padding:9px;max-width:90%;margin:8px}}</style><main><h1>印章与贴纸：逐项覆盖清单</h1><p>{len(rows)}项分类 · 核对于2026-11-12。{data['scope']}。原版图案均未内置；“部分可做”指通用数字效果或原创图案，不等于品牌商品已加入。</p><p><a href="craft-guide.html">素材与示例</a> · <a href="../?tab=library">打开素材库</a> · <a href="craft-coverage.json">下载分类数据</a></p><input id="q" aria-label="搜索品牌或分类" placeholder="搜索品牌、分类或缺失项"><select id="status" aria-label="按状态筛选"><option value="">全部状态</option><option>部分可做</option><option>尚未支持</option></select><p id="count"></p><div class="scroll"><table><thead><tr><th>品牌</th><th>分类</th><th>状态</th><th>可做内容</th><th>仍缺内容</th><th>来源</th></tr></thead><tbody>{body}</tbody></table></div><p>没有把历史款、限定款或联名款当作已经收齐。新增48种原创图案各提供彩色与线稿版本，共96件；素材数量与品牌分类数量分别统计。</p><script>const q=document.querySelector('#q'),s=document.querySelector('#status'),rows=[...document.querySelectorAll('tbody tr')];function filter(){{let n=0;for(const r of rows){{r.hidden=!(r.textContent.toLowerCase().includes(q.value.toLowerCase())&&(!s.value||r.children[2].textContent===s.value));if(!r.hidden)n++;}}document.querySelector('#count').textContent='显示 '+n+' / '+rows.length+' 项';}}q.oninput=filter;s.onchange=filter;filter();</script></main></html>'''
(root/'docs/craft-coverage.html').write_text(html,encoding='utf-8');print(json.dumps({'categories':len(rows),'brands':4}))
